import org.json.*;import java.util.*;import java.nio.file.*;import kotlin.jvm.functions.Function1;
public final class OfficialV10Check {
 public static void main(String[] args)throws Exception{
  JSONArray fixtures=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8")).getJSONArray("fixtures");JSONObject f=fixtures.getJSONObject(Integer.parseInt(args[1]));final List<String> names=new ArrayList<>(),types=new ArrayList<>();final long start=System.nanoTime();final long[] first={0};final Thread caller=Thread.currentThread();
  Function1 callback=new Function1(){public Object invoke(Object link){try{if(Thread.currentThread()!=caller)throw new AssertionError("Callback on catalog thread");String name=(String)link.getClass().getMethod("getName").invoke(link),url=(String)link.getClass().getMethod("getUrl").invoke(link);if(!url.startsWith("https://")||!name.contains("RO Dub"))throw new AssertionError("Invalid source");if(first[0]==0)first[0]=(System.nanoTime()-start)/1000000;names.add(name);types.add(link.getClass().getMethod("getType").invoke(link).toString());if(names.size()>3)throw new AssertionError("Stream cap exceeded");System.out.println("SOURCE "+name);return null;}catch(Exception e){throw new RuntimeException(e);}}};
  if(args.length>2){NativeHttp.CURRENT.set(new NativeHttp.Session(30000));try{List<NativeCatalog.Candidate> candidates=f.getString("site").equals("DeseneFaine")?new NativeCatalog().discover(f.getJSONObject("data")):f.getString("site").equals("DozaAnimata")?new DozaCatalog().discover(f.getJSONObject("data")):f.getString("site").equals("DeseneleDublate")?new DdCatalog().discover(f.getJSONObject("data")):new FdCatalog().discover(f.getJSONObject("data"));for(NativeCatalog.Candidate c:RoDubbedProvider.order(candidates))try{callback.invoke(RoDubbedProvider.makeLink(RoDubbedProvider.resolve(c)));if(names.size()==3)break;}catch(Exception e){System.out.println("HOST SKIP "+c.host+": "+e.getMessage());}}finally{NativeHttp.session().stop();NativeHttp.CURRENT.remove();}}
  else{Object returned=new RoDubbedProvider().loadLinks(f.getJSONObject("data").toString(),false,null,callback,null);if(!Boolean.TRUE.equals(returned))throw new AssertionError("loadLinks false");}
  if(names.size()<f.optInt("minimum",1)||names.size()>3)throw new AssertionError("Unexpected source count "+names.size());if(f.has("requireSite")){boolean found=false;for(String name:names)if(name.endsWith(" | "+f.getString("requireSite")))found=true;if(!found)throw new AssertionError("Required site missing");}
  if(NativeHttp.CURRENT.get()!=null)throw new AssertionError("Session not cleared");System.out.println(new JSONObject().put("title",f.getString("title")).put("pass",true).put("firstSourceMs",first[0]).put("totalMs",(System.nanoTime()-start)/1000000).put("sources",new JSONArray(names)).put("types",new JSONArray(types)));System.exit(0);
 }
}
